<script setup>
/**
 * ProductCard.vue - 文创商品卡片
 * 
 * 展示内容:
 * - 商品图片
 * - 商品名称
 * - 价格
 * - 原价 (划线价)
 * - 销量
 * 
 * Props:
 * - product: object - 商品数据对象
 *   { id, name, cover, price, originalPrice, sales, category }
 * 
 * Emits:
 * - add-to-cart: 点击加入购物车时触发
 */

defineProps({
  product: {
    type: Object,
    required: true
  }
})

const emit = defineEmits(['add-to-cart'])

// 处理加入购物车
const handleAddToCart = (e) => {
  e.stopPropagation()
  emit('add-to-cart', product)
}

// 计算折扣
const getDiscount = (price, originalPrice) => {
  if (!originalPrice || originalPrice <= price) return null
  return Math.round((1 - price / originalPrice) * 100)
}
</script>

<template>
  <div class="product-card" v-if="product">
    <!-- 图片区域 -->
    <div class="image-wrapper">
      <img
        :src="product.cover || (product.images && product.images[0]) || '/images/product-placeholder.jpg'"
        :alt="product.name"
        class="product-image"
        loading="lazy"
      />
      <!-- 折扣标签 -->
      <span
        class="discount-badge"
        v-if="getDiscount(product.price, product.originalPrice)"
      >
        -{{ getDiscount(product.price, product.originalPrice) }}%
      </span>
      <!-- 购物车按钮 -->
      <button
        class="add-cart-btn"
        @click="handleAddToCart"
        title="加入购物车"
        aria-label="加入购物车"
      >
        🛒
      </button>
    </div>

    <!-- 内容区域 -->
    <div class="card-body">
      <h3 class="product-name">{{ product.name }}</h3>

      <!-- 价格区域 -->
      <div class="price-row">
        <span class="current-price">¥{{ product.price?.toFixed(2) || '0.00' }}</span>
        <span
          class="original-price"
          v-if="product.originalPrice && product.originalPrice > product.price"
        >
          ¥{{ product.originalPrice.toFixed(2) }}
        </span>
      </div>

      <!-- 销量 -->
      <div class="sales-row">
        <span class="sales-count">已售 {{ product.sales || 0 }}</span>
        <span v-if="product.category" class="product-category">{{ product.category }}</span>
      </div>
    </div>
  </div>
</template>

